rule_config.rego:
package tracelet.policy

import rego.v1

default matched := false
default reason := ""

tool_input := ti if {
	ti := object.get(input.event, ["raw_json", "tool_input"], {})
	is_object(ti)
}

default tool_input := {}

candidate_texts contains t if {
	some k in ["content", "new_string", "new_str", "text", "code", "contents"]
	t := object.get(tool_input, k, "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	some e in object.get(tool_input, "edits", [])
	is_object(e)
	t := object.get(e, "new_string", "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	t := object.get(input.event, "command_text", "")
	is_string(t)
	t != ""
}

scan_text := concat("\n", [t | some t in candidate_texts])

file_path := object.get(input.event, "file_path", "")

# Region literals written into IaC / SDK config. Edit `allowed_regions` to
# your organisation's approved list (default: EU regions).
allowed_regions := {
	"eu-west-1", "eu-west-2", "eu-west-3",
	"eu-central-1", "eu-central-2",
	"eu-north-1", "eu-south-1", "eu-south-2",
}

region_literal_re := `(?i)(?:\bregion\b|AWS_(?:DEFAULT_)?REGION|LocationConstraint|CDK_DEFAULT_REGION)\s*[=:]\s*['"]?([a-z]{2}(?:-gov|-iso[a-z]*)?-[a-z]+-\d)`

found_regions contains r if {
	some m in regex.find_all_string_submatch_n(region_literal_re, scan_text, -1)
	r := lower(m[1])
}

offending contains r if {
	some r in found_regions
	not allowed_regions[r]
}

matched if {
	scan_text != ""
	count(offending) > 0
}

reason := sprintf("Region %v written to %s is outside the approved data-residency allowlist (%v) — pick an approved region or get the allowlist updated", [sort(offending), display_path, sort(allowed_regions)]) if {
	matched
}

display_path := file_path if { file_path != "" }
display_path := "the command" if { file_path == "" }
